   <meta name="viewport" content="width=device-width, initial-scale=1" />
   <title>Northstar Modern | Retail Home</title>
   <meta
     name="description"
     content="A clean retail home page with featured products, limited-time deals, and editorial stories."
   />
   <style>
     :root {
       color-scheme: light;
       --bg: #f5f1eb;
       --surface: #ffffff;
       --surface-2: #f0ece6;
       --text: #1f1a17;
       --muted: #645b55;
       --line: #d8cfc6;
       --brand: #1f4a5a;
       --brand-strong: #163642;
       --accent: #b85c38;
       --accent-soft: #f2c7b5;
       --success: #215b3d;
       --shadow: 0 18px 40px #231f1a1a;
       --radius-xl: 32px;
       --radius-lg: 24px;
       --radius-md: 16px;
       --radius-sm: 12px;
       --max: 1160px;
     }

     * {
       box-sizing: border-box;
     }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top left, #fff8f0 0, #fff8f0 16%, transparent 17%),
         radial-gradient(circle at top right, #ecf5f8 0, #ecf5f8 13%, transparent 14%),
         var(--bg);
       color: var(--text);
       line-height: 1.5;
     }

     a {
       color: inherit;
       text-decoration-thickness: 0.12em;
       text-underline-offset: 0.15em;
     }

     img,
     svg {
       max-width: 100%;
       display: block;
     }

     button,
     a {
       transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease, color 160ms ease;
     }

     :focus-visible {
       outline: 3px solid var(--brand);
       outline-offset: 3px;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       z-index: 20;
       padding: 0.9rem 1.1rem;
       border-radius: 999px;
       background: var(--brand);
       color: #ffffff;
       transform: translateY(-180%);
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     .shell {
       width: min(100%, var(--max));
       margin: 0 auto;
       padding: 0 1rem 3rem;
     }

     .topbar {
       display: flex;
       justify-content: center;
       padding: 0.85rem 1rem;
       border-bottom: 1px solid var(--line);
       background: var(--surface);
       font-size: 0.95rem;
       color: var(--muted);
     }

     .topbar strong {
       color: var(--text);
     }

     header {
       position: sticky;
       top: 0;
       z-index: 10;
       backdrop-filter: blur(16px);
       background: color-mix(in srgb, var(--bg) 82%, white 18%);
       border-bottom: 1px solid color-mix(in srgb, var(--line) 80%, white 20%);
     }

     .header-inner {
       width: min(100%, var(--max));
       margin: 0 auto;
       padding: 1rem;
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 1.5rem;
     }

     .brand {
       display: inline-flex;
       align-items: center;
       gap: 0.75rem;
       font-weight: 800;
       letter-spacing: 0.02em;
       text-decoration: none;
       white-space: nowrap;
     }

     .brand-mark {
       width: 2.5rem;
       height: 2.5rem;
       border-radius: 14px;
       background: linear-gradient(135deg, var(--brand), var(--accent));
       box-shadow: inset 0 1px 0 #ffffff66;
     }

     nav ul {
       display: flex;
       flex-wrap: wrap;
       gap: 1rem;
       list-style: none;
       margin: 0;
       padding: 0;
     }

     nav a {
       color: var(--muted);
       font-weight: 600;
       text-decoration: none;
     }

     nav a:hover,
     nav a:focus-visible {
       color: var(--brand);
     }

     .hero {
       display: grid;
       grid-template-columns: 1.3fr 0.9fr;
       gap: 1.5rem;
       align-items: stretch;
       padding: 1.5rem 0 2rem;
     }

     .hero-main,
     .hero-aside,
     .panel {
       background: var(--surface);
       border: 1px solid var(--line);
       border-radius: var(--radius-xl);
       box-shadow: var(--shadow);
     }

     .hero-main {
       padding: clamp(1.4rem, 3vw, 2.6rem);
       display: grid;
       gap: 1.25rem;
       align-content: start;
       min-width: 0;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       width: fit-content;
       padding: 0.4rem 0.8rem;
       border-radius: 999px;
       background: var(--surface-2);
       color: var(--brand-strong);
       font-size: 0.92rem;
       font-weight: 700;
     }

     h1,
     h2,
     h3,
     p {
       margin: 0;
     }

     h1 {
       font-size: clamp(2.4rem, 5vw, 4.8rem);
       line-height: 0.98;
       letter-spacing: -0.05em;
       max-width: 11ch;
     }

     .hero-copy {
       max-width: 58ch;
       font-size: 1.06rem;
       color: var(--muted);
     }

     .hero-actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.85rem;
     }

     .button,
     .button-secondary {
       display: inline-flex;
       align-items: center;
       justify-content: center;
       gap: 0.5rem;
       min-height: 3rem;
       padding: 0.85rem 1.1rem;
       border-radius: 999px;
       text-decoration: none;
       font-weight: 700;
     }

     .button {
       background: var(--brand);
       color: #ffffff;
       border: 1px solid var(--brand);
     }

     .button:hover,
     .button:focus-visible {
       background: var(--brand-strong);
       color: #ffffff;
       transform: translateY(-1px);
     }

     .button-secondary {
       background: var(--surface);
       color: var(--text);
       border: 1px solid var(--line);
