        <div class="deal-chart" aria-hidden="true">
          ${deal.bars.map((height) => `<span class="bar" style="min-height:${height}px"></span>`).join('')}
        </div>
      </article>
    `;

    const renderStoryCard = (story) => `
      <article class="card story-card">
        <div class="story-art" aria-hidden="true"></div>
        <div class="story-meta">
          <span class="badge">${story.date}</span>
          <span>${story.meta}</span>
        </div>
        <div class="card-body" style="padding: 0;">
          <p class="card-kicker">${story.section}</p>
          <h3>${story.title}</h3>
          <p>${story.summary}</p>
          <a class="card-link" href="#stories" aria-label="Read story: ${story.title}">Read story</a>
        </div>
      </article>
    `;

    const renderNav = () => `
      <nav aria-label="Primary">
        <ul>
          ${navLinks.map(([label, href]) => `<li><a href="${href}">${label}</a></li>`).join('')}
        </ul>
      </nav>
